class DemoUe(LteUe):
    """DemoUe class provides simple ue implementation for usage demonstration purpose."""
    data_transfer_types = {
        # tool   implementing class
        'iperf': IperfDataTransfer,
    }

    def __init__(self, name, configuration=None):
        """

        :param name:
        :param configuration:
        """
        super().__init__(name, configuration)
        if 'id' in self._configuration:
            self.ue_id = self._configuration['id']
        self.logger = ute_ue_logging.LoggerAdapter4EmptyExtra(self.logger, {'area': 'UE', 'ue_id': name})
        self.logger.info(f'"{name}" instance of DemoUe created: ')
        self._log_arguments("", {'name': name, 'configuration': configuration})
        self.ne_id = UeIdentification(identifiers=[('demo', name)], network_elem_type='UE',
                                      specific_for_tool='demo')
        # State information of UE
        self.attached = False

        self.voice_call_ongoing = False
        self.ongoing_data_transfers = 0
        self._console = CommandSender()
        self._configured_pdns_by_id = [1]

    def attach(self, timeout=-1, **kwargs):
        """
        Perform attach on UE.

        :return: None
        :raises: :py:class:`ute_ue.exceptions.UeProcedureError`: If attach failed
        """
        self.logger.info('attach')

        # Logic Needed from UE
        if self.attached is False:
            if self._console.send(command=f"attach ue id={self.ue_id}"):
                self.attached = True  # perform Attach
                self.logger.info('attach succeeded')
            else:
                exc = UeProcedureError(f"UE {self.name} attach failed")
                self.logger.error(f'{exc!r}')
                raise exc
        else:
            exc = UeProcedureError(f"UE {self.name} already attached")
            self.logger.error(f'{exc!r}')
            raise exc

    def detach(self, timeout=-1, **kwargs):
        """
        Perform detach on UE.

        No action if UE is already detached.

        :return: None
        :raises: :py:class:`ute_ue.exceptions.UeProcedureError`: If detach failed
        """
        self.logger.info('detach')

        # Logic Needed from UE
        if self.attached is True:
            self.voice_call_ongoing = False
            self.ongoing_data_transfers = 0
            if self._console.send(command=f"detach ue id={self.ue_id}"):
                self.attached = False  # perform Attach
                self.logger.info('detach succeeded')
            else:
                exc = UeProcedureError(f"UE {self.name} detach failed")
                self.logger.error(f'{exc!r}')
                raise exc
        else:
            exc = UeProcedureError(f"UE {self.name} already detached")
            self.logger.error(f'{exc!r}')
            raise exc

    def start_data_transfer(self, name, **kwargs):
        """
        Starts data transfer on UE.
        Performs attach if UE is not attached.
        :param name: name to be assigned to starting transfer. You must use it later on to reference given transfer.
        :return: None
        :raises: :py:class:`ute_ue.exceptions.UeProcedureError`: If starting data transfer failed
        """
        # :param dt_definition: object of DataTransferDefinition that encapsulates all needed parameters.
        self.logger.info('start data transfer')
        if 'dt_definition' in kwargs:
            dt_definition = kwargs.get('dt_definition')
        else:
            dt_definition = DataTransferDefinition(**kwargs)
        self._log_arguments("start_data_transfer", {'name': name, 'dt_definition': dt_definition})
        # Logic Needed from UE
        if self.attached is False:
            raise UeProcedureError(f"Can't start data transfer on detached UE {self.name}")

        return super().start_data_transfer(name, dt_definition=dt_definition)

    def start_voice_call(self, name, **kwargs):
        """
        Start voice call on UE. Performs attach if UE is not attached.
        :param name: name to be assigned to voice call. You can use it later on as a reference to voice call.
        :return: None
        :raises: :py:class:`ute_ue.exceptions.UeProcedureError`: If starting voice call failed
        """
        # :param definition: VoiceCallDefinition(to=phone_number, dialing_timeout=dialing_timeout
        self.logger.info('start voice call')
        if 'definition' in kwargs:
            definition = kwargs.get('definition')
        else:
            definition = VoiceCallDefinition(**kwargs)
        self._log_arguments("start_voice_call", {'definition': definition})

        # Logic Needed from UE
        if self.attached is False:
            raise UeProcedureError(f"Can't start voice call on detached UE {self.name}")

        return super().start_voice_call(name=name, definition=definition)

