    def _create_data_transfer(self, name, dt_definition):
        """
        Creating DemoDataTransfer object.

        :param name: name to be assigned to starting transfer. You must use it later on to reference given transfer.
        :param dt_definition: object of DataTransferDefinition that encapsulates all needed parameters.
        :return: iphy_data_transfer: object derivered from lte_data_transfer class
        """
        # selecting which data transfer type to use is based on two sources:
        # 1) dt_definition that comes from test and speaks in protocol terms (duration, direction, bearer, ...)
        # 2) 'data transfer' field of ue configuration that speaks in tool and lab related terms (unix cmd, IP, port ...)
        if 'data_transfer' in self._configuration:
            dt_configuration = dict(self._configuration['data_transfer'])
            requested_protocol = dt_definition.protocol
            ue_known_transfer_types = dt_configuration.pop('type', {})
            tool = self._get_requested_tool(requested_protocol, ue_known_transfer_types)
            dt_implementation = self.data_transfer_types.get(tool, DemoDataTransfer)

            data_transfer = dt_implementation(name, dt_definition, dt_configuration, logger_name=self.ue_logger_name)
        else:
            data_transfer = DemoDataTransfer(name, dt_definition, self._configuration, logger_name=self.ue_logger_name)
        return data_transfer

    def _get_requested_tool(self, requested_protocol, ue_known_transfer_types=None):
        default_transfer_types = {
            'udp': 'iperf',  # iperf is default tool for udp traffic
            'tcp': 'iperf',  # iperf is default tool for tcp traffic
            'icmp': 'ping',  # ping is default tool for icmp traffic
        }
        transfer_types = default_transfer_types
        if ue_known_transfer_types:
            transfer_types.update(ue_known_transfer_types)
        tool = transfer_types.get(requested_protocol, 'unknown')
        return tool

    def _create_bearer(self, qci, pdn, bearer_id, **activation_params):
        """
        Created DemoBearer or DemoDefaultBearer object.

        :param qci: qci of bearer
        :param pdn: pdn of bearer
        :return: DemoBearer instance
        """
        allowed_qcis = (1, 2, 3, 4, 5, 6, 7, 8, 9, 65, 66, 69, 70, 75, 79)
        pdn = pdn if pdn else 1

        if int(qci) not in allowed_qcis:
            raise BearerCreationImpossible('Bearer is not configured')
        if isinstance(pdn, int) or (isinstance(pdn, string_types) and pdn.isdigit()):
            if int(pdn) not in self._configured_pdns_by_id:
                raise BearerCreationImpossible('Bearer is not configured')
        elif pdn not in self._configuration['PDN']:
            raise BearerCreationImpossible('Bearer is not configured')

        bearer_ident = BearerIdentification(
            identifiers=[('demo', {'ue_id': self.name, 'bearer_id': bearer_id, 'pdn_id': pdn, 'qci': qci})],
            network_elem_type='BEARER', specific_for_tool=None)
        if int(qci) == 5:
            return DemoDefaultBearer(bearer_ident)
        return DemoBearer(bearer_ident)

    def _remove_bearer(self, bearer_type):
        """
        Removes bearer object of bearer_type from ue.bearers
        :param bearer_type: bearer_type object
        :return: None
        """
        qci = bearer_type.bearer_identification['qci']
        pdn = bearer_type.bearer_identification['pdn']

        for bearer in self.bearers:
            if bearer.bearer_identification['demo']['pdn_id'] == pdn:
                if bearer.bearer_identification['demo']['qci'] == qci:
                    self.bearers.remove(bearer)

    def activate_dedicated_bearer(self, bearer_type, **activation_params):
        """
        Set active flag for bearer to True.

        :param bearer_type: Bearer object
        :param activation_params: mandatory: filter and precedence
        :return: None
        """
        qci = bearer_type.bearer_identification['qci']
        pdn = bearer_type.bearer_identification['pdn']
        bearer = self._create_bearer(qci=qci, pdn=pdn, bearer_id=1)
        self.bearers.append(bearer)

    def activate_dedicated_bearers(self, bearers):
        """
        Set active flag for bearer to True.

        :param bearers:
        :return: None
        """
        for bearer_name, bearer in bearers.items():
            bearer_type = bearer['bearer_type']
            qci = bearer_type.bearer_identification['qci']
            pdn = bearer_type.bearer_identification['pdn']
            bearer = self._create_bearer(qci=qci, pdn=pdn, bearer_id=abs(int(hash(bearer_name))))
            self.bearers.append(bearer)

    def deactivate_dedicated_bearer(self, bearer_type, **deactivation_params):
        """
        Set active flag for bearer to False.

        :param bearer_type: BearerType object
        :param deactivation_params: not used in DemoBearer
        :return: None
        """
        self._remove_bearer(bearer_type)

    def bearer_is_active(self, bearer_type):
        """
        Checks if bearer of provided type is active for this UE
        :param bearer_type: BearerType object
        :return: True if bearer is active, False if not
        """
        qci = bearer_type.bearer_identification['qci']
        pdn = bearer_type.bearer_identification['pdn']
        return True in [True for bearer in self.bearers
                        if qci == bearer.bearer_identification['demo']['qci'] and pdn == bearer.bearer_identification['demo']['pdn_id']]

    def modify_bearer(self, bearer_type, **modification_params):
        """
        Run bearer_mod command on.

        :param bearer_type: BearerType object
        :param modification_params: mandatory: id, ue, filter, precedence, proto, remote_port, local_port, tos
        :return: None
        :raises: BearerModFailure if mandatory params are missing
        """
        must_have_params = ['filter', 'precedence', 'proto', 'remote_port', 'local_port', 'tos']
        missing_params = [param for param in must_have_params if param not in modification_params]
        if missing_params:
            raise AttributeError(f"BearerModFailure: Missing following mandatory params: {missing_params}")

    def connect_additional_pdn(self, pdn):
        """
        A way to establish additional default bearer.

        :param pdn: PDN logical name (what type of network we want: internet, mms, ...)
        :return: None

        +---------------------------------------------------------+
        |     Example  YAML configuration                         |
        +=========================================================+
        |                                                         |
        | ::                                                      |
        |                                                         |
        |   PDN:                                                  |
        |       default:                                          |
        |           apn: wap.nokia.com                            |
        |           DemoUePool:                                   |
        |               pdp_type: IPV4V6                          |
        |       emergency:                                        |
        |           apn: wap2.nokia.com                           |
        |           DemoUePool:                                   |
        |               pdp_type: Ethernet                        |
        |                                                         |
        +---------------------------------------------------------+

        Specific uepool should extract only data that belongs to it.

        +---------------------------------------------------------+
        |     Extracted configuration data passed to DemoUe       |
        +=========================================================+
        |                                                         |
        | ::                                                      |
        |                                                         |
        |   {'PDN': {                                             |
        |       'default': {                                      |
        |           'apn': 'wap.nokia.com',                       |
        |           'pdp_type': 'IPV4V6'                          |
        |       },                                                |
        |       'emergency': {                                    |
        |           'apn': 'wap2.nokia.com',                      |
        |           'pdp_type': 'Ethernet'                        |
        |       },                                                |
        |   }                                                     |
        |                                                         |
        +---------------------------------------------------------+
        """
        if 'PDN' in self._configuration:
            selected_pdn = self._configuration['PDN'][pdn]
            cmd = "connect pdn ue_id={} apn={} pdp_type={}".format(self.ue_id,
                                                                   selected_pdn['apn'],
                                                                   selected_pdn['pdp_type'])
            self._console.send(command=cmd)
            bearer = self._create_bearer(qci=5, pdn=pdn, bearer_id=1)
            self.bearers.append(bearer)

    def disconnect_additional_pdn(self, pdn):
        """
        A way to release additional default bearer.

        :param pdn: PDN name
        :return: None
        """
        if 'PDN' in self._configuration:
            default_bearer_of_pdn = BearerType({'qci': 5, 'pdn': pdn})
            if not self.bearer_is_active(default_bearer_of_pdn):
                err_msg = f"{self.name} can't disconnect '{pdn}' PDN since it has not been connected"
                raise UeProcedureError(err_msg)
            selected_pdn = self._configuration['PDN'][pdn]
            cmd = "disconnect pdn ue_id={} apn={}".format(self.ue_id,
                                                          selected_pdn['apn'])
            self._console.send(command=cmd)
            self._remove_bearer(default_bearer_of_pdn)

    def create_mbms_session(self, service_name):
        """
        Creating MbmsSession object.

        :param service_name: service_name of session used to isolate proper stream
        :return: mbms_session - object derivered from MbmsSession class
        """
        mbms_session = DemoMbmsSession(service_name, self._configuration)
        return mbms_session

    def _log_arguments(self, method_name, arguments):
        arg_values = [f"{arg}={val}" for arg, val in arguments.items()]
        arguments_text = '{}{}({})'.format(self.__class__.__name__,
                                           f".{method_name}" if method_name else "",
                                           ", ".join(arg_values))
        self.logger.debug(arguments_text)

    def shutdown(self):
        """
        Shutdown
        :return:
        """
        self._console.send(command=f"disconnect ue id={self.ue_id}")

